it('should add a todo successfully', async () => {
  const consoleSpy = vi.spyOn(console, 'log');
  await addTodo('Test todo');
  expect(db.execute).toHaveBeenCalledWith('INSERT INTO todos (text) VALUES (?)', ['Test todo']);
  expect(consoleSpy).toHaveBeenCalledWith('Todo added successfully');
});

it('should handle error when adding todo fails', async () => {
  const error = new Error('Database error');
  db.execute.mockRejectedValueOnce(error);
  const consoleSpy = vi.spyOn(console, 'error');
  await addTodo('Test todo');
  expect(consoleSpy).toHaveBeenCalledWith('Failed to add todo:', error);
});

it('should get non-deleted todos ordered by id descending', async () => {
  const mockTodos = [{ id: 1, text: 'Todo 1', completed: false, deleted: 0 }];
  db.query.mockResolvedValueOnce(mockTodos);
  const result = await getTodos();
  expect(db.query).toHaveBeenCalledWith('SELECT * FROM todos WHERE deleted = 0 ORDER BY id DESC');
  expect(result).toEqual(mockTodos);
});

it('should return empty array when query returns null', async () => {
  db.query.mockResolvedValueOnce(null);
  const result = await getTodos();
  expect(result).toEqual([]);
});

it('should toggle todo completed status', async () => {
  await toggleTodo(1);
  expect(db.execute).toHaveBeenCalledWith('UPDATE todos SET completed = NOT completed WHERE id = ?', [1]);
});

it('should update todo text successfully', async () => {
  const consoleSpy = vi.spyOn(console, 'log');
  await updateTodo(1, 'Updated text');
  expect(db.execute).toHaveBeenCalledWith('UPDATE todos SET text = ? WHERE id = ?', ['Updated text', 1]);
  expect(consoleSpy).toHaveBeenCalledWith('Todo updated successfully');
});

it('should throw error and log when update fails', async () => {
  const error = new Error('Update failed');
  db.execute.mockRejectedValueOnce(error);
  const consoleSpy = vi.spyOn(console, 'error');
  await expect(updateTodo(1, 'text')).rejects.toThrow('Update failed');
  expect(consoleSpy).toHaveBeenCalledWith('Failed to update todo:', error);
});

it('should mark todo as deleted successfully', async () => {
  const consoleSpy = vi.spyOn(console, 'log');
  await deleteTodo(1);
  expect(db.execute).toHaveBeenCalledWith('UPDATE todos SET deleted = 1 WHERE id = ?', [1]);
  expect(consoleSpy).toHaveBeenCalledWith('Todo marked as deleted successfully');
});

it('should throw error and log when delete fails', async () => {
  const error = new Error('Delete failed');
  db.execute.mockRejectedValueOnce(error);
  const consoleSpy = vi.spyOn(console, 'error');
  await expect(deleteTodo(1)).rejects.toThrow('Delete failed');
  expect(consoleSpy).toHaveBeenCalledWith('Failed to mark todo as deleted:', error);
});

